methods.confirmCampChoice:
function () {
    const d = this.campDraft;
    if (!d || d.step !== this.campStep || this.phase !== 'reward') return false;
    return d.step === 'event' ? this.chooseEvent(Number(d.key)) : this.chooseRelic(d.key);
}

methods.rollInitialRecruits:
function () {
        this.recruitQuantities={}; roll.call(this);
        if (this.initialDraft) {
            const eligible=Object.values(UnitCatalog).filter(d=>d.enabled&&!d.evolutionOnly&&d.meta.side==='good'&&this.meta.has(d.id)&&isHeroUnit(d.id)&&d.points<=this.capacity()&&d.recruitCost<=this.gold&&(!SILMARIL_HEROES.has(d.uniqueKey||d.id)||this.rank('silmaril')));
            const seen=new Set();
            for (const offer of this.recruitOffers||[]) if (isHeroUnit(offer.id)) {
                const d=UnitCatalog[offer.id];
                if (d.points>this.capacity()||d.recruitCost>this.gold||seen.has(d.uniqueKey||d.id)) {
                    const available=eligible.filter(v=>!seen.has(v.uniqueKey||v.id));
                    if (available.length) offer.id=available[Math.floor(this.rng()*available.length)].id;
                }
                seen.add(UnitCatalog[offer.id]?.uniqueKey||offer.id);
            }
        }
    }

methods.rollCampEvent:
function () {
    this.rng || (this.rng = Ne(Date.now()));
    const pool = LWB_EVENTS.filter(e => !e.cond || e.cond(this));
    this.campEvent = pool[Math.floor(this.rng() * pool.length)] || null;
    this.campResult = null;
}

methods.endRound:
function () {
    if (this.checkRun())
        return;
    const allies = this.alive('good').filter(u => ht(u, Mt.objective) <= Mt.objective.radius);
    const foes = this.alive('evil').filter(u => ht(u, Mt.objective) <= Mt.objective.radius);
    if (this.mission === 'defense' && foes.length >= this.breachCount) {
        this.endRun(false, '적이 방어선을 돌파했습니다.');
        return;
    }
    if (this.mission === 'hold') {
        const _capUp = allies.length > foes.length;
        this.capture = _capUp ? this.capture + 1 : Math.max(0, this.capture - 1);
        if (_capUp) this.bonusCP += 1;
        if (this.capture >= 3) {
            this.finishWave();
            return;
        }
    }
    if (this.mission === 'rescue') {
        if (allies.length && !foes.length) {
            if (!this.rescued && this.meta.has('arnor_warrior')) {
                const _pu = this.spawn('arnor_warrior', 'good', { x: Mt.objective.x, y: Math.min(1380, Mt.objective.y + 60) });
                _pu && this.emit('Event', '포로 해방 — ' + _pu.name + '이(가) 부대에 합류!', { uid: _pu.uid });
            }
            this.rescued = true;
        }
        if (this.rescued)
            this.capture++;
        if (this.capture >= 3) {
            this.finishWave();
            return;
        }
    }
    if (this.mission === 'scouting' && (this.scouts || 0) >= 3) {
        this.finishWave();
        return;
    }
    if (this.mission === 'purge' && this.purgeLairs && !this._lairDownAt && this.purgeLairs.some(u => { const w = this.unit(u); return !w || !w.alive; }))
        this._lairDownAt = this.round;
    if (this.mission === 'purge' && this.purgeLairs && !this.purgeLairs.some(u => { const w = this.unit(u); return w && w.alive; })) {
        this.finishWave();
        return;
    }
    if (this.mission === 'survive' && this.round >= 5) {
        this.finishWave();
        return;
    }
    if (this.mission === 'breakthrough' && this.alive('good').filter(u => u.y > 1200).length >= Math.min(2, this.permanent().length)) {
        this.finishWave();
        return;
    }
    this.emit('RoundEnded', `라운드 ${this.round} 종료`);
    this.beginRound();
}

methods.promoteTroop:
function(uid,target){
    const u=this.unit(uid),o=this.troopPromotionOptions(u).find(o=>o.id===target);if(!o)return false;
    this.promotionError=this.promotionReason(u,o);if(this.promotionError)return false;
    const before=structuredClone(u),from=u.id,budget=this.rosterPoints();
    this.applyTroopProfile(u,target);
    // A larger cavalry footprint must have a legal place before resources are charged.
    const pos=Be(u,{x:u.x,y:u.y},this.alive(),this.terrain||[],160);
    if(!pos||this.rosterPoints()!==budget){Object.keys(u).forEach(k=>delete u[k]);Object.assign(u,before);this.promotionError='기병 배치 공간이 부족합니다. 병사를 옮긴 뒤 다시 선택하세요';return false;}
    Object.assign(u,pos);this.gold-=o.cost;
    if(o.mount&&o.mount!=='spectral'){if(o.mount==='horse')this.horses--;else this.troopMounts[o.mount]--;}
    if(o.remount)delete u.careerMountLost;
    else u.promotionHistory.push({from,to:target,xp:u.xp,kills:u.kills||0,wave:this.wave,tier:o.tier,entryPoints:u.entryPoints});
    this.unlockAch('promoted');this.emit('TroopPromoted',UnitCatalog[from].meta.name_ko+' → '+u.name+' · 최초 '+u.entryPoints+'pt 유지',{uid,from,to:target});
    this.save();return true;
}

methods.troopGateReason:
function(id){
    const d=UnitCatalog[id],gate=TROOP_PROMOTIONS.gates[id];
    if(d?.meta.side==='evil'&&!this.rank('darkpact'))return '어둠의 계약 유물 필요';
    if(gate&&((gate.relic&&!this.rank(gate.relic))||(gate.wave&&this.wave<gate.wave)||(gate.hero&&!this.permanent().some(u=>(UnitCatalog[u.id]?.uniqueKey||u.id).startsWith(gate.hero)))))return gate.label;
    return '';
}
